import{_ as e,o as t,c as i,af as n}from"./chunks/framework.D7SS9GQA.js";const u=JSON.parse('{"title":"更新日志 · XiHan.UI","description":"","frontmatter":{},"headers":[],"relativePath":"changelog.md","filePath":"changelog.md","lastUpdated":1786281946000}'),a={name:"changelog.md"};function r(l,o,d,c,s,g){return t(),i("div",null,[...o[0]||(o[0]=[n('<h1 id="更新日志-·-xihan-ui" tabindex="-1">更新日志 · XiHan.UI <a class="header-anchor" href="#更新日志-·-xihan-ui" aria-label="Permalink to &quot;更新日志 · XiHan.UI&quot;">​</a></h1><p>本文件记录 XiHan.UI 各版本的变更。每条标注 <strong>新增 / 修复 / 优化 / 调整 / 移除</strong> 类别。</p><div class="warning custom-block"><p class="custom-block-title">当前处于重写后、首发前</p><p>现在的 XiHan.UI 是 2026-07-25 起从零重写的框架无关设计系统运行时，13 个公开包（<code>@xihan-ui/*</code>）由 changesets 的 <code>fixed</code> 组锁步同版，当前版本 <code>0.0.0</code>，<strong>尚未发布到 npm</strong>，首个公开版本计划为 <code>1.0.0-alpha.0</code>。</p><p>npm 上的 <code>xihan-ui</code> 是重写前的旧实现，最后一版 <code>0.9.8</code> 发布于 2025-05-25，六个版本已全部在 npm 上标记弃用。两者不是同一套东西，旧包不会再有更新。</p></div><h2 id="未发布-·-框架无关重写-2026-07-25-起" tabindex="-1">未发布 · 框架无关重写（2026-07-25 起） <a class="header-anchor" href="#未发布-·-框架无关重写-2026-07-25-起" aria-label="Permalink to &quot;未发布 · 框架无关重写（2026-07-25 起）&quot;">​</a></h2><h3 id="基座" tabindex="-1">基座 <a class="header-anchor" href="#基座" aria-label="Permalink to &quot;基座&quot;">​</a></h3><ul><li><strong>新增</strong> <code>@xihan-ui/core</code> 结构原语：anatomy、<code>mergeProps</code>、<code>normalizeProps</code>、Scope、context、id 生成，以及浮层定位、虚拟滚动、代码着色三个端口的类型契约</li><li><strong>新增</strong> <code>@xihan-ui/machine</code> 自研薄状态机：定义层、<code>createService</code> 解释器与 vanilla 运行时，受控值绑定与效应生命周期</li><li><strong>新增</strong> <code>@xihan-ui/behavior</code> 交互行为原语：消解层、焦点域、滚动锁、进出场，随后补上条目集合导航（roving tabindex 底座）与首字母连打检索</li><li><strong>新增</strong> <code>@xihan-ui/system</code> 设计令牌体系与主题运行时，令牌从 DTCG 源产出 CSS / JSON / TS 三种形态</li><li><strong>新增</strong> <code>@xihan-ui/styled</code> 纯 CSS 皮肤层，后续补上 reset 层</li><li><strong>新增</strong> <code>@xihan-ui/core</code> 全局诊断通道，状态机错误投递进该通道而不是抛在使用者脸上</li></ul><h3 id="适配器" tabindex="-1">适配器 <a class="header-anchor" href="#适配器" aria-label="Permalink to &quot;适配器&quot;">​</a></h3><ul><li><strong>新增</strong> <code>@xihan-ui/vue</code> Vue 3 适配器，Button / Dialog 纵切片先打穿全链路</li><li><strong>新增</strong> <code>@xihan-ui/wc</code> Web Components 适配器，Light DOM 行为宿主；<code>xh-dialog</code> 把「有状态组件也能框架无关」这件事验证掉</li><li><strong>新增</strong> WC 侧观察 Light DOM 增删并重新接线，抹平「运行期增删条目」上的适配器分叉</li><li><strong>新增</strong> WC 角色节点契约校验与 Custom Elements Manifest 生成，两者都进门禁</li><li><strong>新增</strong> 跨适配器一致性套件（conformance）：同一批判据在两套宿主上逐帧比对归一化后的 DOM，套件数从 1 个扩到 42 个，排除项改为显式登记</li><li><strong>调整</strong> playground 拆成 <code>playground-vue</code> 与 <code>playground-wc</code> 两个独立包，一环境一包</li></ul><h3 id="组件" tabindex="-1">组件 <a class="header-anchor" href="#组件" aria-label="Permalink to &quot;组件&quot;">​</a></h3><ul><li><strong>新增</strong> 69 个组件逐批铺开，每个都同时产出无头内核、Vue 组件、自定义元素与默认皮肤：从 Button / Dialog 起，经 Switch、Checkbox / Collapsible / Separator、Toggle / Progress / Badge、RadioGroup / Tabs / Accordion、Tooltip / Popover、Menu、Select / Avatar / Field、NumberField，到日期族与最后一批，双适配器铺满</li><li><strong>新增</strong> alert / spinner / skeleton / empty-state 四个反馈类组件</li><li><strong>新增</strong> Checkbox 三态</li><li><strong>调整</strong> Select 支持多选，选中值由单值改为集合：<code>SelectValueChangeDetails.value</code> 由 <code>string | null</code> 变 <code>string[]</code>，<code>SelectApi</code> 的 <code>value</code> / <code>valueText</code> 变数组，<code>setValue</code> 签名变 <code>(next: string | string[]) =&gt; void</code>；Vue 侧 <code>update:value</code> 载荷与 WC 侧 <code>value-change</code> 的 <code>detail</code> 随之变化。见<a href="./components/select">选择器</a></li></ul><h3 id="自研替换第三方" tabindex="-1">自研替换第三方 <a class="header-anchor" href="#自研替换第三方" aria-label="Permalink to &quot;自研替换第三方&quot;">​</a></h3><ul><li><strong>新增</strong> <code>@xihan-ui/position</code> 自研浮层定位引擎（包含块解析、缩放换算、翻面与避让、跟随更新），<strong>移除</strong> <code>@floating-ui/dom</code></li><li><strong>新增</strong> 自研虚拟滚动内核，<strong>移除</strong> <code>@tanstack/virtual-core</code></li><li><strong>新增</strong> WC 自研响应式基类，<strong>移除</strong> <code>@lit/reactive-element</code></li><li><strong>新增</strong> <code>@xihan-ui/markdown</code> 自研解析与渲染，<strong>移除</strong> <code>markdown-it</code></li><li><strong>新增</strong> 代码着色走端口，内置自研粗粒度词法器，可换 Shiki</li><li><strong>调整</strong> 至此全部库包的运行时第三方依赖只剩一个（<code>@internationalized/date</code>，仅日期族使用）。见<a href="./npm-package-dependency">包与依赖关系</a></li></ul><h3 id="ai-与-markdown" tabindex="-1">AI 与 Markdown <a class="header-anchor" href="#ai-与-markdown" aria-label="Permalink to &quot;AI 与 Markdown&quot;">​</a></h3><ul><li><strong>新增</strong> <code>@xihan-ui/ai</code> 协议内核与 AI 组件族第一批：SSE 读取、协议归一、parts 归约、会话 store，配 Thread / Composer / CodeBlock 三件与粘底原语，双适配器</li><li><strong>新增</strong> <code>@xihan-ui/markdown</code> 流式渲染内核，增量切块 + 稳定 key + 消毒</li><li><strong>优化</strong> Markdown 接上 CommonMark 官方用例的一致率棘轮，逐步实现缩进代码块、Setext 标题、跨行链接引用定义与列表松紧排布，一致率由 375 提升至 489</li></ul><h3 id="视觉层" tabindex="-1">视觉层 <a class="header-anchor" href="#视觉层" aria-label="Permalink to &quot;视觉层&quot;">​</a></h3><ul><li><strong>新增</strong> <code>@xihan-ui/visual</code>：WebGL2 背景效果与数据驱动粒子点云，框架无关、零第三方依赖。流场跑片元着色器、粒子走 <code>gl.POINTS</code>，两通道共用同一段 GLSL；内置 14 个效果，不支持 WebGL2 时降级为 CSS 静态背景</li><li><strong>新增</strong> 两个适配器接上视觉层，各走独立子入口 <code>@xihan-ui/vue/visual</code> 与 <code>@xihan-ui/wc/visual</code>，<code>@xihan-ui/visual</code> 声明为可选 peer</li><li><strong>修复</strong> 修复画面在真实页面里一片空白的三个成因</li></ul><h3 id="图标" tabindex="-1">图标 <a class="header-anchor" href="#图标" aria-label="Permalink to &quot;图标&quot;">​</a></h3><ul><li><strong>新增</strong> Icon 原语：<code>IconRecord</code> / <code>IconNode</code> / <code>IconTag</code> 类型、<code>connectIcon</code>、<code>XhIcon</code>、<code>&lt;xh-icon&gt;</code> 与 <code>icon.css</code>。图标数据是结构化节点数组而非 SVG 字符串，渲染端逐节点建元素，运行期不经 HTML 解析器</li><li><strong>移除</strong> 旧 <code>@xihan-ui/icons</code>（27 个第三方图标集的聚合，约四万个图标）整包移除并在 npm 上弃用，重写为只收自研图标的首方集，第一批 29 个覆盖组件库自用的全部语义</li></ul><h3 id="无障碍与质量门禁" tabindex="-1">无障碍与质量门禁 <a class="header-anchor" href="#无障碍与质量门禁" aria-label="Permalink to &quot;无障碍与质量门禁&quot;">​</a></h3><ul><li><strong>新增</strong> 无障碍扫描接上真实浏览器 runner 与 axe，逐个组件扫</li><li><strong>新增</strong> 键盘规格表机读化，作为测试的分母：用例少覆盖一条即判套件失败</li><li><strong>新增</strong> 产物契约门禁（publint + attw）、foundation 层框架无关门禁、依赖拓扑门禁</li><li><strong>修复</strong> 存量无障碍违规登记表清零，由 24 条降到 2 条（WC 侧 <code>steps</code> 一条，外加一条步骤重放豁免）</li><li><strong>修复</strong> 令牌 <code>fg-subtle</code> 达到 AA，并给对比度立下判据</li><li><strong>修复</strong> 焦点陷阱抓不住第一次逃逸；移除持有焦点的条目后不再让整组脱离 Tab 序列；删掉文件上传条目后把焦点交回投放区</li><li><strong>修复</strong> 浮层族改用 fixed 坐标系，不再被 overflow 祖先裁掉</li><li><strong>修复</strong> 挡住输入法组合态</li><li><strong>修复</strong> Dialog 三处：模态背景失活、非模态焦点域、收起态 hidden</li><li><strong>修复</strong> Field 的名字关联不再依赖 control 是可标注元素；Splitter root 不再输出 <code>aria-orientation</code></li><li><strong>修复</strong> 消解层只在展开期间入栈，不再与开合无关地常驻</li><li><strong>修复</strong> 状态机停机后送入的事件一律静默丢弃，dev 下不再抛</li></ul><h3 id="工程" tabindex="-1">工程 <a class="header-anchor" href="#工程" aria-label="Permalink to &quot;工程&quot;">​</a></h3><ul><li><strong>调整</strong> 皮肤层令牌成为唯一事实源，删掉全部字面量兜底，跨组件共享的默认值全部令牌化</li><li><strong>调整</strong> 全仓注释改为只讲功能，不带设计过程引用</li><li><strong>调整</strong> 行尾一律 LF（<code>.gitattributes</code>），署名统一为 XiHanFun and contributors</li><li><strong>新增</strong> changesets 发布配置就绪：13 个公开包锁步同版，私有包不发布不计版</li></ul><h2 id="旧实现-·-xihan-ui-2024-11-2025-07" tabindex="-1">旧实现 · xihan-ui（2024-11 ~ 2025-07） <a class="header-anchor" href="#旧实现-·-xihan-ui-2024-11-2025-07" aria-label="Permalink to &quot;旧实现 · xihan-ui（2024-11 ~ 2025-07）&quot;">​</a></h2><p>重写前的 XiHan.UI 是一套面向 Vue 的常规组件库，<code>ui/packages/</code> 下分 cli、components、constants、directives、hooks、locales、plugins、themes、utils 与聚合包 xihan-ui 共十个子包，对外只发一个 <code>xihan-ui</code>。</p><p>npm 上共发布过六个版本，<strong>全部已标记弃用</strong>，弃用说明为「该版本属重构前的旧实现，已停止维护」：</p><table tabindex="0"><thead><tr><th>版本</th><th>npm 发布日期</th></tr></thead><tbody><tr><td>0.9.8</td><td>2025-05-25</td></tr><tr><td>0.9.7</td><td>2025-05-25</td></tr><tr><td>0.9.0</td><td>2025-03-23</td></tr><tr><td>0.8.20</td><td>2025-03-22</td></tr><tr><td>0.8.19</td><td>2025-03-22</td></tr><tr><td>0.8.18</td><td>2025-03-22</td></tr></tbody></table><p>这一时期的提交信息绝大多数是「优化」「测试」这类无区分度的描述，不足以还原每个版本各自改了什么，因此不逐版展开。从可辨认的记录看，主要工作集中在：工程与打包架构搭建（turbo、子包拆分、发布脚本）、图标子包与图标生成脚本、插件 / 指令 / hooks / 主题 / locales 等子包的建立与重构、组件国际化、以及一个 EventBus 实现。</p>',27)])])}const p=e(a,[["render",r]]);export{u as __pageData,p as default};
